draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // dog body
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // dog legs
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 30);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 20, H/2 + 70);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 30);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 20, H/2 + 70);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50 - 20, H/2 + 70);
  ctx.lineTo(W/2 + Math.sin(t) * 50 - 40, H/2 + 100);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50 + 20, H/2 + 70);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + 40, H/2 + 100);
  ctx.stroke();

  // dog tail
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2 + 30);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + Math.cos(t) * 50, H/2 + 70);
  ctx.stroke();

  ctx.restore();
}
